function Reconstruct(w, K, L):
    result <- 0
    for j in JI(L):
        if j <= K:
            result <- max(result, w[j])
    return result

function CertifiedRecovery(oracle, L):
    JI <- {j in L | SupIrred(j)}
    w <- ExtractWeights(oracle|_JI, L)
    f_hat <- Reconstruct(w, ., L)
    return f_hat, Certificate(JI, w)

algorithms.code:
def certified_recovery(lattice, oracle):
    """Recover functional from oracle queries on JI only."""
    ji = lattice.join_irreducibles()
    weights = {j: oracle(j) for j in ji}
    def f_hat(K):
        vals = [weights[j] for j in ji if lattice.le(j, K)]
        return max(vals) if vals else 0
    return f_hat, weights
